import java.util.*;
import java.io.*;

public class F {
    public static void main(String[] args) throws Exception {
        DataInputStream dis = new DataInputStream(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n = readInt(dis);
        int K = readInt(dis);
        int[][] segments = new int[K][2];
        long totalDiff = 0;
        for (int i = 0; i < K; i++) {
            segments[i][0] = readInt(dis);
            segments[i][1] = readInt(dis);
            totalDiff += segments[i][1] - segments[i][0];
        }
        int[] dpe = new int[n + 1];
        int[] dpo = new int[n + 1];
        Arrays.fill(dpe, 99999999);
        Arrays.fill(dpo, 99999999);
        if (segments[0][0] > n) {
            pw.println("Hungry");
            pw.flush();
            return;
        }
        dpe[segments[0][0]] = 0;
        for (int i = 0; i < K; i++) {
            int[] newDpo = new int[n + 1];
            int[] newDpe = new int[n + 1];
            Arrays.fill(newDpo, 99999999);
            Arrays.fill(newDpe, 99999999);
            Deque<Integer> dq1 = new ArrayDeque<>();
            int w = segments[i][1] - segments[i][0];
            for (int j = 0; j <= n; j++) {
                while (!dq1.isEmpty() && dpe[dq1.peekLast()] >= dpe[j]) dq1.pollLast();
                while (!dq1.isEmpty() && dq1.peekFirst() < j - w) dq1.pollFirst();
                dq1.offerLast(j);
                newDpo[j] = Math.min(newDpo[j], dpe[dq1.peekFirst()] + 1);
                if (j + w <= n) newDpe[j + w] = Math.min(newDpe[j + w], dpe[j]);
            }
            for (int j = 0; j <= n; j++) {
                while (!dq1.isEmpty() && dpo[dq1.peekLast()] >= dpo[j]) dq1.pollLast();
                while (!dq1.isEmpty() && dq1.peekFirst() < j - w) dq1.pollFirst();
                dq1.offerLast(j);
                newDpe[j] = Math.min(newDpe[j], dpo[dq1.peekFirst()] + 1);
                newDpo[j] = Math.min(newDpo[j], dpo[j]);
            }
            dpo = newDpo;
            dpe = newDpe;
            for (int j = 0; j <= n; j++) {
                dpe[j] = Math.min(dpe[j], dpo[j] + 1);
                dpo[j] = Math.min(dpo[j], dpe[j] + 1);
            }
            int s = (i == K - 1 ? 2 * n : segments[i + 1][0]) - segments[i][1];
            for (int j = n; j >= s; j--) {
                dpe[j] = dpe[j - s];
            }
            for (int j = Math.min(n, s - 1); j >= 0; j--) {
                dpe[j] = 99999999;
            }
        }
        int res = Math.min(dpe[n], dpo[n]);
        if (res >= 9999999) {
            pw.println("Hungry");
        } else {
            pw.println("Full");
            pw.println(res);
        }
        pw.flush();
    }

    static int readInt(DataInputStream dis) throws IOException {
        int ret = 0;
        boolean neg = false;
        int c = dis.read();
        while (c != -1 && (c < '0' || c > '9') && c != '-') c = dis.read();
        if (c == '-') {
            neg = true;
            c = dis.read();
        }
        while (c >= '0' && c <= '9') {
            ret = ret * 10 + c - '0';
            c = dis.read();
        }
        return neg ? -ret : ret;
    }
}
